// change trade size to 10 and buy corn
await page.locator('[data-action="trade-size"][data-size="10"]').click()
await page.waitForTimeout(200)
await page.locator('[data-action="trade"][data-side="buy"][data-good="corn"]').click()
await page.waitForTimeout(250)
s=await save(); console.log('after buy corn x10', {cash:s.cash, cargo:s.cargo.corn, weight:Object.entries(s.cargo).reduce((t,[k,v])=>t+v.qty*({wheat:5,corn:8,barley:4,oats:4,hay:6,rice:5,salt:4,honey:3,wool:2,saffron:1}[k]||0),0)})
await shot('market-after-buys')
// sell wheat
await page.locator('[data-action="trade"][data-side="sell"][data-good="wheat"]').click()
await page.waitForTimeout(200)
s=await save(); console.log('after sell wheat', {cash:s.cash, cargo:s.cargo.wheat||null, trades:s.trades, profit:s.profit})
// roads tab
await page.locator('.tab-button[data-tab="roads"]').click()
await page.waitForTimeout(350)
await shot('roads')
const routeCount = await page.locator('.route-tile').count()
console.log('route tiles', routeCount)
console.log('first route', await page.locator('.route-tile').first().innerText())
// travel
await page.locator('.route-tile .travel-button').first().click()
await page.waitForTimeout(350)
await shot('travel-confirm')
console.log('modal title', await page.locator('.modal-title').first().innerText())
await page.locator('[data-action="travel-start"]').click()
await page.waitForTimeout(900)
await shot('travel-result')
s=await save(); console.log('after travel', {city:s.cityId, day:s.day, cash:s.cash, health:s.health, energy:s.energy, hunger:s.hunger, thirst:s.thirst, events:s.events})
const choices = await page.locator('[data-action="event-choice"]').count()
console.log('event choices', choices)
if (choices) {
  console.log('event', await page.locator('.encounter h4').innerText())
  await page.locator('[data-action="event-choice"]').first().click()
  await page.waitForTimeout(400)
  await shot('event-outcome')
  s=await save(); console.log('after event', {cash:s.cash, health:s.health, energy:s.energy, hunger:s.hunger, thirst:s.thirst, events:s.events})
}
// close any modal
if (!(await page.locator('#modal-root').evaluate(e=>e.hidden))) {
  const close = page.locator('[data-action="close-modal"]')
  if (await close.count()) await close.last().click()
  await page.waitForTimeout(250)
}
// caravan tab
await page.locator('.tab-button[data-tab="caravan"]').click()
await page.waitForTimeout(400)
await shot('caravan')
const rigButtons = await page.locator('[data-action="rig-buy"]').allTextContents()
console.log('rig buttons', rigButtons)
// buy first affordable enabled rig
const enabledRig = page.locator('[data-action="rig-buy"]:not([disabled])').first()
if (await enabledRig.count()) {
  const label = await enabledRig.innerText(); const rig = await enabledRig.getAttribute('data-rig')
  await enabledRig.click(); await page.waitForTimeout(350)
  s=await save(); console.log('bought rig', {rig, label, transport:s.transport, cash:s.cash})
  await shot('caravan-after-rig')
}
// atlas tab
await page.locator('.tab-button[data-tab="atlas"]').click()
await page.waitForTimeout(400)
await shot('atlas')
const atlasCities = await page.locator('[data-action="atlas-city"]').count()
console.log('atlas cities', atlasCities)
await page.locator('[data-action="atlas-city"]').nth(5).click()
await page.waitForTimeout(300)
await shot('atlas-city')
// help modal
