await page.waitForTimeout(350)
await shot('help')
await page.locator('[data-action="close-modal"]').first().click()
await page.waitForTimeout(200)
// save reload continue
const before = await save()
await page.reload({waitUntil:'load'})
await page.waitForTimeout(300)
const contVisible = await page.locator('#continue-game').isVisible()
console.log('continue visible', contVisible)
await page.locator('#continue-game').click()
await page.waitForTimeout(600)
const after = await save()
console.log('reload same city/cash', before.cityId===after.cityId, before.cash===after.cash)
console.log('body', await page.evaluate(()=>({sw:document.body.scrollWidth, sh:document.body.scrollHeight, cw:innerWidth, ch:innerHeight, scrollY:window.scrollY})))
console.log('ERRORS', errors)
await browser.close()
