for(const f of ['app.js','art.js','data.js','engine.js','icons.js','journey.js','modals.js','panels.js','views.js']){
  const s=fs.readFileSync(f,'utf8');
  const imports=[...s.matchAll(/import\s*\{([^}]+)\}\s*from\s*['"][^'"]+['"]/gs)].flatMap(m=>m[1].split(',').map(x=>x.trim()).filter(Boolean));
  const unused=imports.filter(n=>{const count=(s.match(new RegExp('\\b'+n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','g'))||[]).length;return count<=1});
  if(unused.length) console.log(f,'unused:',unused.join(', '));
}
